const Panier = ({ cart }) => (
  <PageLayout title="Panier">
    <div className="max-w-2xl mx-auto bg-white/10 p-12 rounded-[3.5rem] text-white font-bold italic">
      {cart.length === 0 ? <p className="text-center opacity-60">Panier vide.</p> : cart.map((item, i) => <div key={i} className="flex justify-between border-b border-white/10 py-4"><span>{item.name}</span><span>{item.price} DH</span></div>)}
